 "content": "def transform(grid):
    """Project each 3-ring marker across the perpendicular 2-line field."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # 2-lines are nearly complete straight lines; markers can replace the
    # three cells where a line crosses their 3x3 pattern.
    row_lines = [r for r in range(h) if sum(v == 2 for v in grid[r]) >= w - 3]
    col_lines = [c for c in range(w) if sum(grid[r][c] == 2 for r in range(h)) >= h - 3]

    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] != 2:
                continue
            if all(grid[rr][cc] == 3
                   for rr in (r - 1, r, r + 1)
                   for cc in (c - 1, c, c + 1)
                   if (rr, cc) != (r, c)):
                centers.append((r, c))

    def paint(r, c):
        if out[r][c] == 0:
            out[r][c] = 1

    if col_lines:
        # A vertical field projects each marker along its row.
        for r, c in centers:
            if c not in col_lines:
                continue
            for cc in range(w):
                paint(r, cc)
            for other_c in col_lines:
                if other_c == c:
                    continue
                for rr in range(max(0, r - 1), min(h, r + 2)):
                    for cc in range(max(0, other_c - 1), min(w, other_c + 2)):
                        if (rr, cc) != (r, other_c):
                            paint(rr, cc)
    elif row_lines:
        # A horizontal field projects each marker along its column.
        for r, c in centers:
            if r not in row_lines:
                continue
            for rr in range(h):
                paint(rr, c)
            for other_r in row_lines:
                if other_r == r:
                    continue
                for rr in range(max(0, other_r - 1), min(h, other_r + 2)):
                    for cc in range(max(0, c - 1), min(w, c + 2)):
                        if (rr, cc) != (other_r, c):
                            paint(rr, cc)
    return out
